/**
 * `agent-sdk logs` — follow a running server's `/v1/logs`, or a hosted v2
 * deployment's session output.
 *
 * Customer-facing output never includes hosting URLs, tokens, or infra jargon.
 */
import { isRecord } from "./is-record.js";
import { mergeRequestHeaders } from "./request-headers.js";
import { stderrPalette } from "./terminal-style.js";
const DEFAULT_POLL_INTERVAL_MS = 1_000;
/** Re-read abort state after await (loop narrowing would hide async abort). */
function isAborted(signal) {
    return signal?.aborted === true;
}
function isLogRingEntry(value) {
    return (isRecord(value) &&
        typeof value.index === "number" &&
        typeof value.at === "string" &&
        typeof value.line === "string");
}
const PROGRESS_MESSAGES = {
    queued: "Waiting to start…",
    preparing: "Preparing runtime…",
    creating: "Creating runtime…",
    building: "Checking out source…",
    starting: "Starting agent and waiting for health…",
    finalizing: "Finishing deployment…",
    running: "Deployment running",
    failed: "Deploy failed",
    stopping: "Stopping deployment…",
    stopped: "Deployment stopped",
    deleting: "Deleting deployment…",
    degraded: "Deployment degraded",
};
/** Strip obvious hosting internals from error text shown to customers. */
export function sanitizeCustomerError(message) {
    return message
        .replace(/https?:\/\/(?!cursor\.com\/dashboard\/)\S+/gi, "[url]")
        .replace(/\bpod-[a-z0-9]+\b/gi, "[runtime]")
        .replace(/\banyrun\b/gi, "runtime")
        .replace(/\bcursorvm\.com\b/gi, "host")
        .replace(/\bx-anyrun-[a-z0-9-]+\b/gi, "header")
        .replace(/\bPROVISIONING\b/g, "building")
        .replace(/\bPLANNED\b/g, "preparing")
        .replace(/\bgitCloneCheckout\b/gi, "git clone")
        .replace(/\bgitFetchCheckout\b/gi, "git fetch")
        .replace(/\bgitCheckout:clone\b/gi, "checkout")
        .replace(/\bgitCheckout:fetch\b/gi, "checkout");
}
/**
 * One-line label for `agent-sdk deploy` polling (TTY spinner / non-TTY
 * transitions). Uses statusMessage → progress → raw status.
 *
 * Deliberately does NOT include `lastError`. The spinner redraws with
 * `\r\x1b[2K`, which clears one physical row, so a reason long enough to
 * soft-wrap would leave the earlier rows on screen. Callers print the
 * reason once on the final line instead.
 */
export function deployProgressLabel(detail) {
    if (detail.statusMessage !== null &&
        detail.statusMessage !== undefined &&
        detail.statusMessage.trim() !== "") {
        return detail.statusMessage
            .trim()
            .replace(/…$/, "")
            .replace(/\.\.\.$/, "");
    }
    if (detail.progress !== undefined) {
        return PROGRESS_MESSAGES[detail.progress].replace(/…$/, "").replace(/\.\.\.$/, "");
    }
    return detail.status;
}
export async function fetchLogs(args) {
    const fetchImpl = args.fetchImpl ?? fetch;
    const after = args.after ?? -1;
    const url = new URL(`${args.baseUrl.replace(/\/$/, "")}/v1/logs`);
    if (after >= 0) {
        url.searchParams.set("after", String(after));
    }
    const resp = await fetchImpl(url, {
        headers: mergeRequestHeaders(args.auth),
        signal: args.signal,
    });
    if (!resp.ok) {
        throw new Error(`Could not fetch logs (HTTP ${resp.status}).`);
    }
    const body = await resp.json();
    const record = isRecord(body) ? body : {};
    const entries = Array.isArray(record.entries) ? record.entries.filter(isLogRingEntry) : [];
    const nextAfter = typeof record.nextAfter === "number"
        ? record.nextAfter
        : entries.length === 0
            ? after
            : (entries[entries.length - 1]?.index ?? after);
    return { entries, nextAfter };
}
/** Follow a running server's `/v1/logs` (local `serve` or `--url`). */
export async function runLogsTail(options) {
    const write = options.write ?? ((text) => void process.stdout.write(text));
    const err = options.err ?? ((text) => void process.stderr.write(text));
    const sleep = options.sleep ?? sleepMs;
    const intervalMs = options.intervalMs ?? DEFAULT_POLL_INTERVAL_MS;
    const baseUrl = (options.url ?? "http://127.0.0.1:3000").replace(/\/$/, "");
    if (options.once !== true) {
        err(stderrPalette().dim("Tailing logs… (Ctrl-C to stop)\n"));
    }
    await followRuntimeLogs({
        baseUrl,
        auth: { bearerToken: options.bearerToken },
        once: options.once === true,
        json: options.json === true,
        fetchImpl: options.fetchImpl,
        signal: options.signal,
        intervalMs,
        write,
        sleep,
    });
}
async function followRuntimeLogs(args) {
    let after = -1;
    for (;;) {
        if (isAborted(args.signal)) {
            return;
        }
        let batch;
        try {
            batch = await fetchLogs({
                baseUrl: args.baseUrl,
                after,
                auth: args.auth,
                fetchImpl: args.fetchImpl,
                signal: args.signal,
            });
        }
        catch (error) {
            if (isAborted(args.signal)) {
                return;
            }
            throw error instanceof Error ? error : new Error("Could not fetch logs.");
        }
        for (const entry of batch.entries) {
            if (args.json) {
                args.write(`${JSON.stringify({
                    type: "log",
                    index: entry.index,
                    at: entry.at,
                    line: entry.line,
                })}\n`);
            }
            else {
                args.write(`${entry.line}\n`);
            }
        }
        after = batch.nextAfter;
        if (args.once) {
            return;
        }
        await args.sleep(args.intervalMs, args.signal);
    }
}
/** Same poll cadence as the portal's logs view. */
const HOSTED_POLL_INTERVAL_MS = 5_000;
/** Sessions whose last read is kept for diffing. Older ones age out. */
const HOSTED_TRACKED_SESSIONS = 100;
/**
 * `logs --prod` on architecture v2: poll the recent sessions' output and print
 * lines not seen yet. Like `tail -f` over several files, a `==> ses_… <==`
 * header marks each switch to another session.
 */
export async function followHostedLogs(options) {
    const write = options.write ?? ((text) => void process.stdout.write(text));
    const err = options.err ?? ((text) => void process.stderr.write(text));
    const sleep = options.sleep ?? sleepMs;
    const seen = new Map();
    let current;
    if (!options.once) {
        err(stderrPalette().dim(`Tailing logs for ${options.slug}… (Ctrl-C to stop)\n`));
    }
    while (!isAborted(options.signal)) {
        let sessions;
        try {
            sessions = await options.read(options.signal);
        }
        catch (error) {
            if (isAborted(options.signal)) {
                return;
            }
            throw error;
        }
        for (const session of sessions) {
            // A session's output never shrinks to empty, so an empty read missed.
            // Keep the last one or the next read reprints it all.
            if (session.lines.length === 0) {
                continue;
            }
            const fresh = unseenLines(seen.get(session.sessionId) ?? [], session.lines);
            remember(seen, session.sessionId, session.lines);
            if (fresh.length === 0) {
                continue;
            }
            if (!options.scoped && !options.json && current !== session.sessionId) {
                const channel = session.channelId === undefined ? "" : ` (${session.channelId})`;
                write(`${current === undefined ? "" : "\n"}==> ${session.sessionId}${channel} <==\n`);
            }
            current = session.sessionId;
            for (const line of fresh) {
                write(options.json
                    ? `${JSON.stringify({ type: "log", sessionId: session.sessionId, line })}\n`
                    : `${line}\n`);
            }
        }
        if (options.once) {
            return;
        }
        await sleep(options.intervalMs ?? HOSTED_POLL_INTERVAL_MS, options.signal);
    }
}
/**
 * Lines of `next` past the longest suffix of `prev` that starts `next`. The
 * server returns a sliding tail, so one snapshot is not a prefix of the next.
 */
function unseenLines(prev, next) {
    for (let overlap = Math.min(prev.length, next.length); overlap > 0; overlap--) {
        const start = prev.length - overlap;
        let index = 0;
        while (index < overlap && next[index] === prev[start + index]) {
            index++;
        }
        if (index === overlap) {
            return next.slice(overlap);
        }
    }
    return [...next];
}
/** Map order is recency: the first key is the stalest session. */
function remember(seen, sessionId, lines) {
    seen.delete(sessionId);
    seen.set(sessionId, lines);
    for (const oldest of seen.keys()) {
        if (seen.size <= HOSTED_TRACKED_SESSIONS) {
            return;
        }
        seen.delete(oldest);
    }
}
async function sleepMs(ms, signal) {
    if (isAborted(signal)) {
        return;
    }
    await new Promise((resolve) => {
        const timer = setTimeout(() => {
            signal?.removeEventListener("abort", onAbort);
            resolve();
        }, ms);
        const onAbort = () => {
            clearTimeout(timer);
            resolve();
        };
        signal?.addEventListener("abort", onAbort, { once: true });
    });
}
